import sys,math;sys.path.insert(0,'.')
from common7 import *
SN=E('Information Technology','ኢንፎርሜሽን ቴክኖሎጂ')
def U(n,title,extra,exam,nt,summ,foot):
    unit(f'g7-it-{n}','it',SN,E(f'Unit {n}',f'ክፍል {n}'),E(*title),E(f'Built on the Grade 7 Information Technology student text (MoE), Unit {n}: {foot[0]}.',f'በ7ኛ ክፍል የኢንፎርሜሽን ቴክኖሎጂ መጽሐፍ (ትምህርት ሚኒስቴር) ክፍል {n} ላይ የተመሰረተ፦ {foot[1]}።'),'(d=>[])',{},extra,exam,nt,summ)
def turtle(n,side,label):
    x,y,h=0.0,0.0,0.0;pts=[(x,y)]
    for i in range(n):
        x+=side*math.cos(math.radians(h));y+=side*math.sin(math.radians(h));pts.append((x,y));h-=360/n
    xs=[p[0] for p in pts];ys=[p[1] for p in pts];mx,my=min(xs),min(ys);W=max(xs)-mx;H=max(ys)-my;s=110/max(W,H)
    P=' '.join(f'{10+(px-mx)*s:.1f},{10+(H-(py-my))*s:.1f}' for px,py in pts)
    return f'<svg viewBox="0 0 130 130" style="width:130px;height:auto" role="img" aria-label="{label}"><polyline points="{P}" fill="none" stroke="var(--blue,#2b6cb0)" stroke-width="4" stroke-linejoin="round"/><circle cx="{10+(pts[0][0]-mx)*s:.1f}" cy="{10+(H-(pts[0][1]-my))*s:.1f}" r="5" fill="var(--ink)"/></svg>'

